changeSet.sql:
ALTER TABLE stock_receipts ADD COLUMN status VARCHAR(20) NOT NULL DEFAULT 'POSTED', ADD COLUMN document_date DATE, ADD COLUMN receipt_type VARCHAR(40), ADD COLUMN default_markup_percent NUMERIC(8, 2), ADD COLUMN invoice_number VARCHAR(80), ADD COLUMN invoice_date DATE, ADD COLUMN contract_number VARCHAR(80), ADD COLUMN financial_discount NUMERIC(18, 2), ADD COLUMN payment_type VARCHAR(20), ADD COLUMN total_retail NUMERIC(18, 2) NOT NULL DEFAULT 0, ADD COLUMN activated_at TIMESTAMPTZ, ADD COLUMN activated_by UUID REFERENCES users (id);
UPDATE stock_receipts SET document_date = (created_at AT TIME ZONE 'Asia/Tashkent')::date WHERE document_date IS NULL;
CREATE INDEX IF NOT EXISTS idx_stock_receipts_status ON stock_receipts (status);

CREATE TABLE stock_lots (
    id UUID PRIMARY KEY,
    product_id UUID NOT NULL REFERENCES products (id),
    store_id INTEGER NOT NULL REFERENCES stores (id),
    receipt_line_id UUID REFERENCES stock_receipt_lines (id),
    batch_number VARCHAR(80),
    expiry_date DATE,
    quantity NUMERIC(18, 3) NOT NULL DEFAULT 0,
    purchase_price NUMERIC(18, 2) NOT NULL DEFAULT 0,
    unit_selling_price NUMERIC(18, 2) NOT NULL DEFAULT 0,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX idx_stock_lots_product_store ON stock_lots (product_id, store_id);
CREATE INDEX idx_stock_lots_expiry ON stock_lots (expiry_date);
CREATE INDEX idx_stock_lots_batch ON stock_lots (batch_number);
